// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address proposedNewOwner) public {
        vm.assume(caller != address(0));
        vm.assume(proposedNewOwner != address(0));

        address ownerAddr = address(0xABCD);
        vm.prank(address(0));
        c.transferOwnership(ownerAddr);

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(proposedNewOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || c.owner() == proposedNewOwner);
    }
}
